class Solution {public:vector<vector<int>>solve(vector<vector<int>>g){int m=g.size(),n=m?g[0].size():0;vector<vector<int>>d(m,vector<int>(n));vector<pair<int,int>>q;for(int r=0;r<m;r++)for(int c=0;c<n;c++){d[r][c]=g[r][c]==1?-2:-1;if(g[r][c]==2){d[r][c]=0;q.push_back({r,c});}}int dr[]={-1,1,0,0},dc[]={0,0,-1,1};for(int i=0;i<(int)q.size();i++){auto [r,c]=q[i];for(int k=0;k<4;k++){int x=r+dr[k],y=c+dc[k];if(x>=0&&x<m&&y>=0&&y<n&&d[x][y]==-1){d[x][y]=d[r][c]+1;q.push_back({x,y});}}}return d;}};